url = "https://aspose-pdf-cloud1.p.rapidapi.com/pdf/{name}/images/{imageId}/extract/png"
querystring = {"imageId": "", "folder": "", "width": 0, "height": 0, "storage": "", "name": ""}

headers = {
            "X-RapidAPI-Key": "SIGN-UP-FOR-KEY",
            "X-RapidAPI-Host": "aspose-pdf-cloud1.p.rapidapi.com"
        }

response = requests.get(url, headers=headers, params=querystring)
print(response.json())

